create or replace function public.system_initialize_profile(p_name text,p_age integer,p_gender text,p_class text,p_fingerprint text default null,p_profile_data jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare v_user uuid:=auth.uid(); v_profile public.profiles; v_attributes public.attributes; v_class text:=upper(trim(coalesce(p_class,'COMMANDER'))); begin if v_user is null then raise exception 'AUTH_REQUIRED'; end if; if length(trim(coalesce(p_name,'')))<2 then raise exception 'INVALID_NAME'; end if; if p_age is null or p_age<13 or p_age>120 then raise exception 'INVALID_AGE'; end if; if v_class not in ('COMMANDER','TANK','ASSASSIN','MAGE') then raise exception 'INVALID_CLASS'; end if; insert into public.profiles(id,name,age,gender,class,level,xp,streak,momentum,fingerprint,profile_data,current_class_since) values(v_user,trim(p_name),p_age,nullif(trim(coalesce(p_gender,'')),''),v_class,1,0,0,0,p_fingerprint,coalesce(p_profile_data,'{}'::jsonb) - array['xp','level','streak','momentum','attributes','masteredSkills','bossQuests','rewards','customInventory']::text[],now()) on conflict(id) do update set name=excluded.name,age=excluded.age,gender=excluded.gender,fingerprint=coalesce(public.profiles.fingerprint,excluded.fingerprint),profile_data=coalesce(public.profiles.profile_data,'{}'::jsonb)||excluded.profile_data,updated_at=now() returning * into v_profile; insert into public.attributes(user_id,strength,speed,endurance,intelligence,focus,discipline,wealth,charisma,creativity,recovery) values(v_user,10,10,10,10,10,10,10,10,10,10) on conflict(user_id) do nothing; select * into v_attributes from public.attributes where user_id=v_user; return jsonb_build_object('profile',to_jsonb(v_profile),'attributes',to_jsonb(v_attributes)); end $$;
create or replace function public.system_update_profile_identity(p_name text default null,p_age integer default null,p_gender text default null,p_profile_data jsonb default null) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare v_user uuid:=auth.uid(); v_profile public.profiles; begin if v_user is null then raise exception 'AUTH_REQUIRED'; end if; if p_name is not null and length(trim(p_name))<2 then raise exception 'INVALID_NAME'; end if; if p_age is not null and (p_age<13 or p_age>120) then raise exception 'INVALID_AGE'; end if; update public.profiles set name=coalesce(nullif(trim(p_name),''),name),age=coalesce(p_age,age),gender=case when p_gender is null then gender else nullif(trim(p_gender),'') end,profile_data=case when p_profile_data is null then profile_data else coalesce(profile_data,'{}'::jsonb)||(p_profile_data-array['xp','level','streak','momentum','attributes','masteredSkills','bossQuests','rewards','customInventory']::text[]) end,updated_at=now() where id=v_user returning * into v_profile; if not found then raise exception 'PROFILE_NOT_READY'; end if; return to_jsonb(v_profile); end $$;
create or replace function public.system_create_goal(p_title text,p_category text,p_target numeric,p_unit text default null,p_deadline date default null) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare v_user uuid:=auth.uid(); v_goal public.goals; begin if v_user is null then raise exception 'AUTH_REQUIRED'; end if; if length(trim(coalesce(p_title,'')))<2 then raise exception 'INVALID_GOAL_TITLE'; end if; if p_target is null or p_target<=0 then raise exception 'INVALID_GOAL_TARGET'; end if; insert into public.goals(user_id,title,category,target_value,current_value,unit,deadline,status,xp_reward,metadata) values(v_user,trim(p_title),upper(coalesce(p_category,'OTHER')),p_target,0,nullif(trim(coalesce(p_unit,'')),''),p_deadline,'ACTIVE',300,jsonb_build_object('created_by','SYSTEM_API')) returning * into v_goal; return to_jsonb(v_goal); end $$;
create or replace function public.system_update_goal_progress(p_goal_id bigint,p_current numeric) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare v_user uuid:=auth.uid(); v_goal public.goals; begin if v_user is null then raise exception 'AUTH_REQUIRED'; end if; if p_current is null or p_current<0 then raise exception 'INVALID_GOAL_PROGRESS'; end if; update public.goals set current_value=least(p_current,target_value),status=case when status='COMPLETE' then status else 'ACTIVE' end where id=p_goal_id and user_id=v_user returning * into v_goal; if not found then raise exception 'GOAL_NOT_FOUND'; end if; return to_jsonb(v_goal); end $$;
create or replace function public.system_claim_goal(p_goal_id bigint) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare v_user uuid:=auth.uid(); v_goal public.goals; v_profile public.profiles; v_attr text; v_reward text; begin if v_user is null then raise exception 'AUTH_REQUIRED'; end if; select * into v_goal from public.goals where id=p_goal_id and user_id=v_user for update; if not found then raise exception 'GOAL_NOT_FOUND'; end if; if v_goal.status='COMPLETE' then return jsonb_build_object('duplicate',true,'goal',to_jsonb(v_goal)); end if; if coalesce(v_goal.current_value,0)<coalesce(v_goal.target_value,0) then raise exception 'GOAL_TARGET_NOT_REACHED'; end if; update public.goals set status='COMPLETE',completed_at=now() where id=v_goal.id returning * into v_goal; select * into v_profile from public.system_award_xp(coalesce(v_goal.xp_reward,300),'GOAL',v_goal.title,jsonb_build_object('goal_id',v_goal.id)); v_attr:=upper(coalesce(v_goal.category,'')); if v_attr in ('STRENGTH','SPEED','ENDURANCE','INTELLIGENCE','FOCUS','DISCIPLINE','WEALTH','CHARISMA','CREATIVITY','RECOVERY') then perform public.system_add_attribute(v_attr,2,'GOAL',v_goal.title,jsonb_build_object('goal_id',v_goal.id)); end if; v_reward:=coalesce(v_goal.reward_name,v_goal.category||' MILESTONE REWARD'); insert into public.rewards(user_id,name,category,source,status,metadata) values(v_user,v_reward,v_goal.category,'GOAL:'||v_goal.id::text,'UNCLAIMED',jsonb_build_object('authoritative',true)); insert into public.journey_events(user_id,event_type,title,detail,source,source_id,xp_delta,metadata) values(v_user,'GOAL_COMPLETED',v_goal.title,'Major goal completed by authoritative backend.','GOAL',v_goal.id::text,coalesce(v_goal.xp_reward,300),jsonb_build_object('category',v_goal.category)); perform public.system_orchestrate_progression(); return jsonb_build_object('goal',to_jsonb(v_goal),'profile',to_jsonb(v_profile),'reward_name',v_reward); end $$;
create or replace function public.system_add_custom_inventory(p_name text,p_type text default 'GEAR',p_rarity text default 'COMMON',p_bonus text default null,p_notes text default null,p_image_path text default null) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare v_user uuid:=auth.uid(); v_item public.user_inventory; begin if v_user is null then raise exception 'AUTH_REQUIRED'; end if; if length(trim(coalesce(p_name,'')))<2 then raise exception 'INVALID_ITEM_NAME'; end if; insert into public.user_inventory(user_id,custom_name,custom_type,rarity,bonus_text,notes,image_path,source_type,source_id,equipped,showcase,metadata) values(v_user,upper(trim(p_name)),upper(coalesce(p_type,'GEAR')),upper(coalesce(p_rarity,'COMMON')),nullif(trim(coalesce(p_bonus,'')),''),nullif(trim(coalesce(p_notes,'')),''),p_image_path,'USER_DECLARED',gen_random_uuid()::text,false,false,jsonb_build_object('user_declared',true,'authoritative_stats',false)) returning * into v_item; return to_jsonb(v_item); end $$;
insert into public.quest_library(code,title,objective,system_message,category,quest_type,difficulty,class_affinity,attribute_reward,attribute_delta,xp_reward,failure_xp_penalty,duration_minutes,min_level,health_value,frequency,active,metadata) values ('EVENT_15_WINDOW','THE 15 MINUTE WINDOW','Choose one small unfinished task and finish it completely.','Unexpected opportunity detected.','FOCUS','RARE','HARD',array[]::text[],null,0,120,0,15,1,4,'RARE',true,jsonb_build_object('event',true)),('EVENT_ZERO_DISTRACTION','ZERO DISTRACTION','Work on one meaningful task without checking another app or site.','Attention lock required.','FOCUS','RARE','HARD',array[]::text[],'FOCUS',1,150,0,20,1,5,'RARE',true,jsonb_build_object('event',true)),('EVENT_RAPID_RESET','RAPID RESET','Clean and organize your immediate environment.','Immediate environment reset.','DISCIPLINE','RARE','NORMAL',array[]::text[],'DISCIPLINE',1,100,0,10,1,3,'RARE',true,jsonb_build_object('event',true)),('EVENT_QUICK_MARCH','QUICK MARCH','Complete an appropriate brisk movement session.','Movement window detected.','PHYSICAL','RARE','HARD',array[]::text[],'ENDURANCE',1,120,0,15,1,4,'RARE',true,jsonb_build_object('event',true)) on conflict(code) do update set active=true,updated_at=now();
revoke all on function public.system_initialize_profile(text,integer,text,text,text,jsonb) from public,anon; revoke all on function public.system_update_profile_identity(text,integer,text,jsonb) from public,anon; revoke all on function public.system_create_goal(text,text,numeric,text,date) from public,anon; revoke all on function public.system_update_goal_progress(bigint,numeric) from public,anon; revoke all on function public.system_claim_goal(bigint) from public,anon; revoke all on function public.system_add_custom_inventory(text,text,text,text,text,text) from public,anon; grant execute on function public.system_initialize_profile(text,integer,text,text,text,jsonb) to authenticated,service_role; grant execute on function public.system_update_profile_identity(text,integer,text,jsonb) to authenticated,service_role; grant execute on function public.system_create_goal(text,text,numeric,text,date) to authenticated,service_role; grant execute on function public.system_update_goal_progress(bigint,numeric) to authenticated,service_role; grant execute on function public.system_claim_goal(bigint) to authenticated,service_role; grant execute on function public.system_add_custom_inventory(text,text,text,text,text,text) to authenticated,service_role;
drop policy if exists profiles_update_own on public.profiles; drop policy if exists profiles_insert_own on public.profiles; drop policy if exists attributes_insert_own on public.attributes; drop policy if exists attributes_update_own on public.attributes; drop policy if exists attributes_delete_own on public.attributes;
